import { uniquePieceBare, ARTILLERY_RULE, SIEGE_RULE, SIEGE_USES_IRON, siegeGold, interceptRule, siegeBonusOf, unitStatsFor, KESHIG_KIND, TANK_MOVES, LANDSHIP_MOVES, AUTONOMOUS_ARMOUR_MOVES, swissInterestRule, swissTollRule, BUILDING_STATS, UNIT_STATS, UNIT_NAME, itemKey, CLASS_BONUS_PERCENT, MOUNTED_CITY_PENALTY_PERCENT, FIRST_GROWTH, MOUNTED_MOVES, START_GOLD, IMPROVEMENT_INFO, FACTIONS, FACTION_INFO, factionGoalVp, RULES, TECH_NAME, buildingStatsFor, CAPTURE_RESISTANCE_TURNS, SETTLER_COST_STEP, WORK_RADIUS, TILE_GOLD_BASE, TILE_GOLD_PER_TILE, tileRingPercent, TECH_DIFFUSION_MAX, TECH_DIFFUSION_PER_EMPIRE, DECADENCE_FOOD_RULE, decadencePercent, decadenceRules, GREAT_WORKS, buildingIconName, HOPLITE_PHALANX_STRENGTH, SPECIAL_UNIT, specialUnitName, specialUnitEdge } from '../data';
import { FACTION_SHEETS } from '../factionSheets';
import { comparedItems, comparisonSentence, pieceComparison } from '../pieceCompare';
