import { RESOURCE_INFO, RESOURCES, STRATEGIC_SITE_VALUE, SUPPLY_PER_DEPOSIT, SUPPLY_PER_MINE, UNSUPPLIED_STRENGTH_PERCENT, isStrategic } from '../resources';
