/** A row of painted unlock miniatures with their names (only the ones painted so far). */
function GuideArtRow({ label, pieces }: { label: string; pieces: { slug: string; name: string; icon?: string }[] }) {
  const shown = pieces.map((p) => ({ ...p, url: slugUrl(p.slug, 128) }));
  if (!shown.length) return null;
  return <div className="guide-unlock-art" aria-label={label}>{shown.map((p) => <figure key={p.slug}>{p.url ? <img src={p.url} alt="" width={64} height={64} /> : p.icon ? <Icon name={p.icon} size={64} /> : null}<figcaption>{p.name}</figcaption></figure>)}</div>;
}
const IMPROVEMENT_PIECES = (['Farm', 'Pasture', 'Quarry', 'Mine'] as ImprovementKind[]).flatMap((k) => [
  { slug: improvementArtSlug(k), name: IMPROVEMENT_INFO[k].name },
  { slug: improvementArtSlug(k, true), name: IMPROVEMENT_INFO[k].upgradedName },
]);
const GREAT_WORK_PIECES = GREAT_WORKS.map((b) => ({ slug: buildingArtSlug(b), name: RULES.buildingNames[b], icon: buildingIconName(b) }));


export const GUIDE_SECTIONS: { id: GuideSection; label: string }[] = [
  { id: 'start', label: 'Begin your campaign' },
  { id: 'turns', label: 'Your first turns' },
  { id: 'cities', label: 'Cities & research' },
  { id: 'combat', label: 'Simultaneous combat' },
  { id: 'victory', label: 'The victory race' },
  { id: 'factions', label: 'The peoples' },
  { id: 'controls', label: 'Controls & saves' },
  { id: 'credits', label: 'Credits' },
];

/** The era table: each era, its resource and what uses it (the era's new units and its key building). */
const ERA_USERS: [string, Resource | null, string][] = [
  ['Ancient', null, 'No resource requirements; Markets and Workshops need nothing'],
  ['Classical', 'Iron', 'Phalangites, Composite Archers, Cataphracts and Forges'],
  ['Medieval', 'Iron', 'Pikemen, Crossbowmen, Knights and Universities'],
  ['Renaissance', 'Niter', 'Musketmen, Arquebusiers, Cuirassiers and Banks'],
  ['Industrial', 'Coal', 'Riflemen, Field Cannons, Cavalry and Factories'],
  ['Machine Age', 'Oil', 'Trench Infantry, Howitzers, Early Tanks and Biplanes'],
  ['World War', 'Oil', 'Infantry, Artillery, Tanks, Fighters, Bombers and Research Labs'],
  ['Modern', 'Oil', 'Mechanised Infantry, Rocket Artillery, Main Battle Tanks, Jet Fighters and Jet Bombers'],
  ['Future', 'Silicon', 'Hunter-Killers, Combat Drones, Autonomous Armour and Stealth aircraft'],
];

export function GuideContent({ section }: { section: GuideSection }) {
  const ruleSwitches = useGame((s) => s.views?.[s.seat]?.rule_experiments);
  const decadence = decadenceRules(ruleSwitches);
  const cut = (lead: number) => decadencePercent(lead, decadence);
  const alliance = allianceTerms();
  const company = RULES.company;
  switch (section) {
    case 'start': return <>
      <p className="guide-lede">Legatum brings peoples from different periods of human history onto one map. Explore ancient ruins, found cities and contest the legacy they leave behind.</p>
      <p>Lead an empire, explore ruins, found cities and race for victory points (VP): reach your target, then hold it. If you know Civilization VI, the pieces will feel familiar. The difference is timing: everyone’s plans resolve together.</p>
      <h3>Choose how you play</h3>
      <div className="guide-modes">
        <section><h4>Single Player</h4><p>You against AI empires. The default is a free-for-all against five AI rivals on a Standard map; change seats and teams in the lobby.</p></section>
        <section><h4>Multiplayer · Hot Seat</h4><p>Share one computer. Each human plans for their own empire, then marks Ready and passes to the next seat.</p></section>
        <section><h4>Multiplayer · Host Game</h4><p>Your browser tab runs the game and lists it so other players can find it. Anyone with the same version can join. Keep that tab open while you play: closing it ends the game for everyone. Give your game a join code to lock it: players type it once to take a seat. Remove takes a player out of a seat and keeps it closed until you open it.</p></section>
        <section><h4>Multiplayer · Join Game</h4><p>See the games that are open now. Choose one, press Join and take an open human seat. A game marked Locked needs the join code from its host.</p></section>

      </div>
      <h3>Make the lobby yours</h3>
      <p>Set names, factions, human or AI seats, and team numbers; close unwanted seats. The same team means shared vision, shared victory and no friendly attacks. Other teams start at Peace, with closed borders. Open Diplomacy from the Victory race to negotiate or declare War.</p>
      <p>Pick a map size, AI difficulty and a map seed. Every empire’s first city gets the same Food and Production from its start tile and the tiles next to it: 8 of each. What lies farther out differs, so scout for your next resources. A game runs about 300 turns. Costs, growth and timers are all set for that length. Movement, combat and yields follow the rules described below.</p>
      <p>A game has no turn limit unless you turn one on. With a turn limit, the game ends after that many turns and the team with the most VP wins. The lobby shows each team’s victory target. Hard AI makes better decisions, but it never gets extra resources.</p>
      <div className="guide-note">If you join a waiting room, take a seat, choose your name and faction, then press Ready. The host starts once everyone is ready. If the host has already started, choose a seat in the running game.</div>
    </>;
    case 'turns': return <>
      <p className="touch-only">Tap any number for its breakdown. Use ⓘ beside an action to inspect it, and Close or tap outside to dismiss.</p>
      <p className="guide-lede">Plan now. Resolve together.</p>
      <ol className="guide-steps">
        <li><h3>Your capital is ready</h3><p>Every empire starts with its capital founded on its starting tile. Choose what it builds on turn 1. Your Scout explores and your Spearman can protect the start.</p></li>
        <li><h3>Give units destinations</h3>
          <p>Select a unit, then right-click a destination or drag from the unit to it. On touch screens, tap a destination to preview its path and battle forecast, then tap it again or Confirm. Hold a tile for context actions. One finger pans and a pinch zooms. Double-tap a selected unit or an inspection tile to zoom. Long routes carry on across turns.</p>
          <p>Fortify (<kbd>F</kbd>) keeps a military unit where it is, healing and strengthening its defences. Wait (<kbd>F</kbd>) keeps civilians in place, healing and resting. Either order lasts until you give another order or an enemy military unit comes into sight within its movement range. This counts whether the enemy arrives there or walks closer. Choosing the order again ignores enemies already that close, until another one arrives. A waiting ranged unit does not fire. Heal (<kbd>H</kbd>) rests a damaged unit the same way until it is back to full health, then returns it to your orders with a notice, so you cannot forget it. Space skips just this turn: the unit asks for orders again next turn. Auto-fire (<kbd>V</kbd>, for volley) keeps a ranged unit in your city, shooting the best visible enemy in range every turn. Its map badge is a crosshair. Auto-explore (<kbd>E</kbd>) sends a Scout or any military unit to explore on its own. It avoids known armies and foreign borders closed to it, rests when hurt, stops when threatened or below 60 HP, and asks for orders when nothing is left to explore.</p>
          <p>On turn 1, Return starts with your capital's build, then steps through units and research. Later it steps through units, idle cities, then research. When every decision is made, Return ends the turn. Choosing Build by mouse, touch or keyboard advances to the next decision. Reopen the city from Cities to inspect it or edit its plan. + Queue and Shift-click keep the panel open.</p></li>
        <li><h3>Choose production and research</h3><p>Select your capital and choose a unit or building, then open Technologies (<kbd>T</kbd>) and pick an available technology. Food grows a city, and Production builds what you choose. A Settler needs population 2. More cities grow your empire. Every empire starts at Peace, so your units can’t attack another empire’s units or cities until one side declares War. Early on, military units mostly guard your cities and escort Settlers.</p></li>
        <li><h3>Ready your empire</h3><p>The This Turn panel helps you find missing orders. In solo play, End turn resolves the turn once you confirm any pending decisions. In multiplayer, Ready locks in your plan, and the turn resolves when every human seat is ready. Hot Seat passes to the next planner. Shift+Return, End Turn and Ready anyway list your unfinished decisions so you can confirm them. Return steps through pending decisions, including the selected unit or city. Once every unit has orders, every city is building something and research is chosen, Return ends the turn or readies your seat.</p></li>
        <li><h3>Read what happened</h3><p>Ranged attacks resolve first, then movement and melee, founding, city output, research and scoring. Check the turn report for battles, discoveries and failed orders, then plan again.</p></li>
      </ol>
      <div className="guide-note">Your opponents’ current positions are visible where you have vision. Their orders are hidden. A unit that pulls back from an adjacent enemy can still be hit as it leaves, but it completes its move if it survives. Armies can collide on an empty tile.</div>
      <h3>Diplomacy: Peace, Alliance or War</h3>
      <ol className="guide-ladder" aria-label="Relations between teams">
        {(['Peace', 'Alliance', 'War'] as const).map((kind) => <li key={kind}><b>{kind}</b> {TREATY_DEFINITION[kind]}</li>)}
      </ol>
      <p>Peace keeps borders closed to foreign units, except an ally’s and the land of whoever holds a Yam Relay Station. Crossing like this is not a provocation.</p>
      <p>You cannot attack a rival you are at Peace with. Declaring War while at Peace is a surprise war. It takes effect at once, so an attack ordered with it resolves the same turn. Signing Peace after War starts a {TREATY_TERMS.guaranteeTurns}-turn truce between the two teams. Neither may declare War on the other or be pulled back into that war by an ally until the shown end turn has passed. Permanent teammates share vision and victory. You can give Gold to a teammate from the Your team section of the diplomacy panel. It arrives next turn, after this turn's purchases, and you can give at most the Gold you had at the start of the turn. Alliances with other teams do not combine victory scores.</p>
      <p>An Alliance gives shared sight and open borders. Each side’s units may enter the other’s land and pass through allied units of the same class, but cannot end on their tiles. Allied cities are also transit-only. It also changes how wars work (see below). Each empire pays {alliance.upkeep} Gold per owned city each turn, and never less than {alliance.upkeep} Gold in all. Its Gold breakdown lists the total as Treaty upkeep.</p>
      <p>No Alliance upkeep while at War with an empire close to winning. An empire is close to winning when it is within 2 VP of its victory target or holding its target. The Alliance pays nothing on any turn either ally is at War with such an empire, and the Gold breakdown shows the upkeep and the waiver as two lines.</p>
      <p>You must have met an empire to offer it an Alliance, which means one of your units or cities has seen one of its units, cities or borders. Peace and War need no contact.</p>
      <p>For its first {alliance.protectedTurns} turns an Alliance is protected: leaving inside that window costs {alliance.breachCost} Gold and is a betrayal. Leaving later is free. Either way, leaving takes effect next turn and returns both teams to Peace. Declaring War on an ally is always a betrayal. It takes effect next turn and ends the Alliance. A betrayed team won’t ally with the betrayer for {alliance.betrayalTurns} turns, and Diplomacy shows who broke an Alliance and until when.</p>
      <p><b>Allies defend each other, and join wars by choice.</b> If an empire declares War on your ally, you are at War with that empire too, in the same turn. If your ally declares War on someone, you get a call to arms: join the war, or decline and stay allied and at Peace with the target. Declining has no penalty and is no betrayal. A call you don’t answer lapses after two turns, which counts as declining. An Alliance that would make an empire fight its own ally cannot be signed, and neither can one that would break a recent peace.</p>
      <p>If either of you is at War when you sign, the offer lists what changes. The new ally joins at once the wars its partner is defending, and gets a call to arms for the wars its partner started.</p>
      <p>A Peace offer is between two teams. Both must agree. It ends only the war between them. Wars with their allies go on, and both Alliances stay. Making Peace on your own is not a betrayal.</p>
      <p><b>Mercenary Companies (Byzantium):</b> a Byzantine city can hire the special unit of any empire it has met and is not at War with. Each empire sells only its own special unit, and the Company is that empire’s version of it. It has that unit’s name, stats and own rules (the Hoplite’s phalanx, the Keshig’s bow), not the empire’s faction-wide rules. That empire must know the unit’s technology and, for a resource unit, own an improved deposit of its resource. Hiring needs no spare supply and uses no supply slot. The price is {company.hirePercent}% of that version’s Production cost, in Gold, and all of it goes to the seller. It uses the city’s one purchase for the turn. The Company appears next turn at level 1, serves {company.turns} turns, then goes home, and costs <Amount n={company.upkeep} unit="Gold" /> a turn while it stays. It fights and captures like any unit, cannot be upgraded and does not count against thin levies. If Byzantium cannot pay its upkeep, a Company turns on it as a barbarian. Every Company shows its seller and its contract countdown on the map, so everyone can see when it leaves.</p>
      <p><b>Thin levies (Byzantium):</b> Byzantium fields at most one military unit per city, plus one more, not counting Scouts. Losing a city never disbands units. It only stops you training new ones until you are back under that limit. The top bar, the city panel and the diplomacy panel show the count.</p>
      <p>Before you commit, every diplomatic action shows its Gold cost, its upkeep, when it takes effect and whether it is a betrayal.</p>
      <p>The Relations tab in Diplomacy shows every met empire’s Peace, Alliance and War relationships in one table.</p>
      <h3>Coming from Civilization VI</h3>
      <p>There are no Builders or districts. Cities work tiles automatically, and they build both buildings and tile improvements as production items. Borders grow as cities gain population, you can buy tiles with Gold, and conquest can extend your territory. Diplomacy is Peace, Alliance or War, with explicit calls to arms. There is no navy yet. Victory is a race for points that everyone can watch, so a rival’s score matters long before you reach their capital.</p>
      <h3>Barbarians</h3>
      <p>Camps appear in the fog from turn {RULES.firstCampTurn}, away from cities and units, as in Civilization VI. Each has a guard that never leaves and a scout. Barbarians are always hostile, so you never need to declare War on them.</p>
      <ul>
        <li><b>Stop raids:</b> kill the scout before it gets home. A scout that saw a city and reaches its camp sends three raiders to prowl around that city, attacking units in the open and capturing Settlers.</li>
        <li><b>Clear a camp:</b> beat the guard, then move any military unit onto the camp for <Amount n={RULES.campClearGold} unit="Gold" />. Settlers held there are freed. Borders that grow over a camp disperse it with no reward.</li>
        <li><b>Unlike Civilization VI,</b> barbarians never assault or take cities, and they never heal.</li>
        <li><b>The Celts</b> are the one empire barbarians never attack: they leave Celtic units, cities and Settlers alone, and never raid a Celtic city.</li>
      </ul>
      <p>Barbarians can be turned off in the game settings. The Celtic goal Raise the Warbands still raises camps when barbarians are off. Borders never disperse those camps, and Celtic players get no Gold for clearing them.</p>
    </>;
    case 'cities': return <>
      <p className="guide-lede">Give every city a job, and enough Food to do it.</p>
      <h3>Raze a captured city</h3>
      <p>From the planning turn after capture, select a city you hold but did not found and choose Raze. The city burns at the turn boundary, its tiles are released and you gain 10 Gold per population. World wonders and faction goal buildings in it are destroyed, along with any VP they give. The Celts instead burn cities automatically on capture for a stronger sack.</p>
      <h3>Growth and production</h3>
      <p>Population is territory. A city works every tile it owns within {WORK_RADIUS} tiles, so you never assign workers. Each population above 1 claims one more tile. What the city is building steers which tile it claims next. Military units (the spear, archer and horse lines) and world wonders favour Production tiles. A Settler in a city below population 2 favours Food. Everything else favours a balance, including idle cities, Scouts and their faction replacements. The yield breakdown shows the emphasis and the reason for it. Each point of population eats 2 Food a turn, and any surplus grows the city.</p>
      <p>Progress bars show everything that builds up over time. In the city panel, Food, Production, Gold and Science per turn are always shown under the city’s population and strength; select a yield for its source breakdown. Compare cities (C) opens the table of your cities. The Growth bar shows stored Food against the Food needed. It also shows the turns to the next population and what that unlocks (a Settler needs population 2). It turns red when the city is starving, with the turns until it loses a population. The same bar is the territory bar. Its label names the tile the next growth claims; “Next tile” under the bar gives that tile’s yield, separate from the city’s per-turn totals. It says “blocks rivals” when that tile lies beyond {WORK_RADIUS} tiles, because you can’t work it.</p>
      <p>The city panel’s Tiles details count the tiles worked and owned. Now producing shows stored Production, Production per turn and turns until completion. Production and world wonders show stored Production against the Production needed. Walls, Castles, Star Forts and Switzerland’s Alpine Redoubt must be built with Production; they can’t be bought with Gold. You can switch away from Walls and return later to finish its banked Production. On the map, each of your city banners carries a Food meter and a Production meter. The Food meter shows the turns until the city grows and claims a tile. Striped own tiles are beyond every own city's work radius: they block rivals but give no yield. Hover one to see which city owns it. The research cell in the top bar fills as Science builds up. When a city grows, the turn report says what the new population unlocks, and a growth that unlocks something gets a card. Each tile a city claims or gives back shows on the map with its terrain and yields.</p>
      <p>A city’s centre and worked tiles always give at least 3 Production in total, before buildings and faction penalties. Workshops add {BUILDING_STATS.Workshop.yields.production} more. Forges add {BUILDING_STATS.MachineShop.yields.production} more. Factories add {BUILDING_STATS.Autoworks.yields.production} more. Germany’s Ruhr Foundry replaces the Forge and gives +{buildingStatsFor('Germany', 'MachineShop').yields.production} Production.</p>
      <h3>Map key</h3>
      <dl className="guide-definitions guide-map-key" aria-label="Map key">
        <div><dt><span className="guide-map-mark claimed-only" aria-hidden="true" /> Blue stripes</dt><dd>Yours, beyond a city’s {WORK_RADIUS}-tile working range: it blocks rivals but yields nothing.</dd></div>
        <div><dt><span className="guide-map-mark dashed-border" aria-hidden="true" /> Dashed borders</dt><dd>Territory line patterns identify empires. A dashed outline marks the selected city’s territory.</dd></div>
        <div><dt><span className="guide-map-mark war-border" aria-hidden="true" /> Red border</dt><dd>An empire you are at War with.</dd></div>
        <div><dt><span className="guide-map-mark siege-ring" aria-hidden="true" /> Red ring</dt><dd>This city is under attack.</dd></div>
        <div><dt><span className="guide-map-mark landmark-tile" aria-hidden="true">◆</span> Landmark</dt><dd>A world wonder built by a city, shown on a nearby tile. Natural wonders are shown on their own tiles too.</dd></div>
      </dl>
      <p>German cities can run an Industry project. Each turn it turns {RULES.germanyProjectGoldPercent}% of the city’s Production into Gold, or {RULES.germanyProjectSciencePercent}% into Science. The project runs until you change it. Its output appears in the city yield breakdown and forecasts. When choosing a build, check the yield breakdown and the city’s completion estimate.</p>
      <p>Production is banked per item, as in Civ 6. If you switch to another build, the old item keeps its progress banked in that city. That progress comes back when you build the same item again, and it never moves to a different item. The new item starts from its own banked progress, or from zero. Production not yet given to an item joins whatever starts next. This covers overflow from a finished item, and Production stored while the city had no build. Each card in the production list shows its own progress (for example 38/75 banked). The city panel lists every banked item, and choosing a different build tells you what stays banked. Banked progress is dropped for a building that now stands, or for a world wonder your empire has completed. Capturing a city clears its banks.</p>
      <p>Items you have researched but this city can’t build yet stay in the list, greyed out. Each one says why and how to fix it. A Settler at population 1 says how many turns until the city reaches population 2, and a building that needs a lower tier says which one. You can’t choose, queue or buy these items. Clicking one only shows why.</p>
      <p>The first trained Settler costs {UNIT_STATS.Settler.cost} Production, and each one after costs {SETTLER_COST_STEP} more. Every Spartan Settler, the first included, costs 50% more. A city needs at least 2 population to choose, queue, continue or buy a Settler. The Settler uses up 1 population when it is done. The first growth, from population 1 to 2, costs {FIRST_GROWTH} Food. If a city building a Settler falls below 2 population, its progress stays banked and the city asks for a new build. Escort your Settlers, because enemy military units can capture them. New cities must be at least four tiles from every existing city, allies’ cities included. India can found them three tiles apart.</p>
      <p>You can buy buildings and units with Gold for twice their Production cost. Switzerland pays 175% instead. Faction cost changes also affect purchases. A purchase completes after Ready. It does not spend stored Production or replace a different build. A bought item is a separate copy at full price, and it never adds to another item’s progress. Each city can buy one item a turn. Units need enough population and room to appear before they move. New units act next turn.</p>
      {ruleSwitches?.no_purchase_under_threat && <p><b>No buying under threat (rule experiment).</b> A city can’t buy a military unit while an enemy unit at War stands within 2 tiles of it. It can still buy buildings, and it can still build units with Production.</p>}
      <p>Your first two military units cost no upkeep. Each extra one costs 1 Gold a turn (3 for Switzerland). Scouts and Settlers never cost upkeep and never use up a free unit. Every empire starts with {START_GOLD} Gold in its treasury. Switzerland’s income: {swissTollRule()} {swissInterestRule()} Capturing a Swiss city takes a share of its owner’s treasury that matches the city’s share of that owner’s population. The share is doubled for a capital and never more than the whole treasury. A negative treasury can force a disband.</p>
      <h3>Borders</h3>
      <p>Population is territory. A new city owns its centre and the tiles around it, and works them all from the first turn. Every time it grows, it claims one more unowned tile next to its border. It claims the nearest tiles first, filling each ring (all the tiles at the same distance from the city) before starting the next. Within a ring it takes the best tile for the city’s focus, and known strategic deposits pull harder. A border can reach as far as growth takes it, but a city only works tiles within {WORK_RADIUS} tiles. At the end of a turn, an out-of-reach tile goes to the nearest city of the same empire that can work it. Tiles no city can work remain yours and block rivals, but give nothing.</p>
      <p>You can also buy a tile with Gold. Select a city, choose Buy a tile, then click a lit tile on the map; each shows its Gold price. A city can buy any explored, unowned tile next to its border within {WORK_RADIUS} tiles, in any order, so you can reach a deposit or get around a neighbour. Farther tiles only come from growth.</p>
      <p>A tile costs {TILE_GOLD_BASE} Gold, plus {TILE_GOLD_PER_TILE} Gold for each tile the city has gained since it was founded, whether it grew or you bought it. Tiles in the second ring cost {tileRingPercent(2)}% of that, and tiles in the third ring {tileRingPercent(3)}%. A tile purchase is the city’s one purchase for the turn, shared with buying units and buildings. A tile you buy is never given back when the city loses population, and the city still gains a tile each time it grows. If two empires buy the same tile on the same turn, a random draw decides who gets it. The other keeps its Gold.</p>
      <p>{TILE_RELEASE_RULE} A city boxed in by rivals catches up on its claims when land frees up. Cities in resistance don’t claim.</p>
      <h3>Resources: strategic supply begins with Iron</h3>
      <div className="guide-resource-art" aria-label="The nine resource deposits">{RESOURCES.map((resource) => <span key={resource}><Icon name={`resource-${resource.toLowerCase()}`} size={28} label={resource} />{resource}{isStrategic(resource) && <small>Strategic</small>}</span>)}</div>
      <p>Medallions at the top of a tile mark resources, as in Civ. A resource gives its bonus only after its tile is improved (see Improvements below): Wheat and Cattle +{RESOURCE_INFO.Wheat.bonus.food} Food, Stone +{RESOURCE_INFO.Stone.bonus.production} Production, Copper +{RESOURCE_INFO.Copper.bonus.gold} Gold. All four are bonus resources and always visible.</p>
      <p>The Ancient era has no resource requirements. From the Classical era on, an era’s new land units and its key building use 1 of that era’s strategic resource.</p>
      <table className="guide-era-table">
        <thead><tr><th>Era</th><th>Resource</th><th>What uses it</th><th>Revealed by</th></tr></thead>
        <tbody>{ERA_USERS.map(([era, resource, users], i) => <tr key={era}>
          <td>{era}</td>
          <td className="guide-resource-cell">{resource ? <span className="guide-resource-label"><Icon name={`resource-${resource.toLowerCase()}`} size={20} /> <b>{resource}</b></span> : 'None'}</td>
          <td>{users}</td>
          <td>{resource ? TECH_NAME[RESOURCE_INFO[resource].revealedBy!] : '—'}{i === 2 && ' (Iron continues)'}</td>
        </tr>)}</tbody>
      </table>
      <p>Everything on offer on turn 1 is free: the Spearman, Archer and Horseman, Settlers and the early buildings. So are Walls, the Granary and Mill, Roadworks, world wonders and faction landmarks. One upgrade order reaches the newest researched unit in its line and pays the sum of each step’s Gold price. A unit that upgrades switches to the final unit’s resource: it gives back the old one and needs 1 spare of the new one. A higher building keeps the needs of the ones below it, so a Factory city uses Iron for its Forge and Coal for the Factory.</p>
      <p>Iron Working reveals Iron on the map. Each later resource appears when you learn its technology: Gunpowder (Niter), Industrialization (Coal), Combustion (Oil) and Autonomous Systems (Silicon). Once revealed, each deposit inside your borders supplies {SUPPLY_PER_DEPOSIT} of its resource, whether or not you work it. Improved, it supplies {SUPPLY_PER_DEPOSIT + SUPPLY_PER_MINE} (a {IMPROVEMENT_INFO.Mine.name}, {IMPROVEMENT_INFO.SaltpeterWorks.name}, {IMPROVEMENT_INFO.OilWell.name} or {IMPROVEMENT_INFO.QuartzMine.name}). German deposits supply twice as much: {2 * SUPPLY_PER_DEPOSIT}, or {2 * (SUPPLY_PER_DEPOSIT + SUPPLY_PER_MINE)} improved. The improvement also adds its tile's yield. Nothing is stored: supply is what your deposits give you right now.</p>
      <p>A building or unit uses its supply for as long as it exists, and a build in progress holds its supply until it finishes. A new building or unit can start, be bought or be upgraded to only while supply is spare. If you don’t have any to spare, the production list says so and how to get more. You can still queue the item behind other work.</p>
      <p>Supply is counted at the end of every turn. When your buildings and units need more than your deposits supply, the newest go idle until supply returns. An idle building stops yielding, and an idle unit fights {UNSUPPLIED_STRENGTH_PERCENT}% weaker. Losing a deposit, or having it taken, can idle your army. Winning one can set it right.</p>
      <p>The top bar shows every revealed strategic resource in its own chip, as “Iron 1 / 6”: spare supply over total supply. Before you reveal your era’s resource, a muted chip names the technology to research and its tooltip names the units and buildings it feeds. Revealed chips open each resource’s breakdown and name what uses it. If your era’s revealed resource is missing, its chip shows an alert and the tooltip names who holds the deposits you have seen. Click it to see every deposit and every building or unit that needs it, and to find the idle ones on the map.</p>
      <p>Every start has a Copper deposit two tiles away and an Iron deposit three to five tiles away, within reach of your borders or a nearby second city. Niter, Coal, Oil and Silicon lie in the borderlands between empires, so the later eras are won by expanding toward them or taking them.</p>
      <p>The Resources overlay (O) rings every known deposit: yours, unclaimed and other empires’. A red “!” marks a deposit of a resource you lack that another empire holds or nobody does. Borders grow toward known strategic deposits, and the settle lens counts known resources (+{STRATEGIC_SITE_VALUE} per strategic deposit within two tiles).</p>
      <h3>Improvements: waking a resource</h3>
      <GuideArtRow label="The improvements and their upgrades" pieces={IMPROVEMENT_PIECES} />
      <p>There are no Builders. A city builds an <b>improvement</b> as a production item, aimed at one tile it owns and works (within {WORK_RADIUS} tiles), such as “Mine, Iron · 2 tiles NE”. Wheat takes a {IMPROVEMENT_INFO.Farm.name}, Cattle a {IMPROVEMENT_INFO.Pasture.name}, Stone a {IMPROVEMENT_INFO.Quarry.name}, Copper, Iron and Coal a {IMPROVEMENT_INFO.Mine.name}, Niter a {IMPROVEMENT_INFO.SaltpeterWorks.name}, Oil an {IMPROVEMENT_INFO.OilWell.name} and Silicon a {IMPROVEMENT_INFO.QuartzMine.name}. Quartz deposits fit for chips are scarce. Your unimproved resources show faded, with a dashed ring (dormant). Improvements cost {IMPROVEMENT_INFO.Farm.cost} to {IMPROVEMENT_INFO.Mine.cost} Production and can be bought like any item. Egypt pays in Food and builds no Quarries.</p>
      <p>Improvements upgrade by themselves as you learn technologies. Masonry gives the Deep Quarry. Iron Working gives the Deep Mine: +{RULES.improvements.forResource.Copper.upgradeYields.gold} Gold on Copper, +{RULES.improvements.forResource.Iron.upgradeYields.production} Production on Iron and +{RULES.improvements.forResource.Coal.upgradeYields.production} Production on Coal. Crop Rotation gives the Irrigated Farm and Ranch. Railways adds another Production to Mines, and Combustion adds Gold to Oil Wells. You never need to rebuild. A captured city keeps its improvements for the captor. A released tile keeps its improvement; razing a city destroys its improvements.</p>
      <h3>Research with a purpose</h3>
      <p>Your capital makes +2 Production and +2 Science a turn, from turn 1. Every city also makes 1 Science for every 2 population. Libraries and their upgrades add more. The city yield breakdown lists the capital bonus separately. Capturing a capital removes its capital bonus, and the captor does not get a second capital. If you lose your capital, the next city you found becomes your new capital. Cities in resistance produce nothing.</p>
      <h3>Eras: research in order</h3>
      <p>There are nine eras: Ancient, Classical, Medieval, Renaissance, Industrial, Machine Age, World War, Modern and Future, with five technologies each. You can research only the unknown technologies of your current era, the first era that still has one. There are no prerequisites inside an era, so you choose the order, and you can queue the whole era at once. If a technology gives your people nothing, you skip it. You know it from the start, and it is not on your research screen. Egypt has no Production, so it skips Bronze Working and its Workshop. Finishing the last technology of an era enters the next era that turn, and every empire sees it. The research screen shows your era, how many of its technologies you know, and the later eras as locked rows.</p>
      <p>A technology costs its listed Science, less tech diffusion. Each other empire that already knows it takes {TECH_DIFFUSION_PER_EMPIRE}% off its cost, up to {TECH_DIFFUSION_MAX}%, and the cost breakdown lists the discount. The queue shows the turn each technology arrives, in the order you set. Reorder it and the forecast follows.</p>
      <dl className="guide-definitions">
        <div><dt>Ancient</dt><dd><Amounts text={`Irrigation (+1 Food in every city), Bronze Working (Workshops), Masonry (Walls), Currency (Markets), Writing (${RULES.buildingNames.Laboratory} for Science). The Granary needs no research.`} /></dd></div>
        <div><dt>Classical</dt><dd>Mathematics unlocks Phalangites (from Spearmen) and Siege. Engineering unlocks Composite Archers (from Archers) and Roadworks. Iron Working reveals Iron, unlocks Cataphracts and Forges, and improves Mines. Code of Laws claims every city’s best tile 2 tiles out. Philosophy unlocks the Great Library and adds 1 Science in every city.</dd></div>
        <div><dt>Medieval</dt><dd>Feudalism unlocks Pikemen (from Phalangites) and Mills. Machinery unlocks Crossbowmen, Hagia Sophia and Star Forts, improves Workshops, and lets Siege reach Castles. Chivalry unlocks Knights, Castles and Sparta’s {RULES.buildingNames.WarShrine}. Education unlocks Universities. Crop Rotation upgrades Farms and Pastures and adds 1 Food per Granary.</dd></div>
        <div><dt>Renaissance</dt><dd>Gunpowder reveals Niter and unlocks Musketmen and Arquebusiers. Metallurgy lets Siege reach Star Forts. Military Engineering halves the Gold cost of upgrading units. Banking unlocks Banks and the Grand Bazaar. Printing Press gives 1 Science per Library and 1 Gold per Market.</dd></div>
        <div><dt>Industrial to Future</dt><dd>Military Science makes land units cost 10% less Production. Ballistics unlocks the Royal Arsenal. Industrialization reveals Coal and unlocks Factories. Railways gives road-start units +{RULES.railwayMoves} moves, extends Roadworks links to 12 tiles, and adds 1 Production to Mines. Machine Age: Replaceable Parts unlocks Trench Infantry and adds 2 Production per Factory. Combustion reveals Oil, unlocks Early Tanks and adds 1 Gold per Oil Well. Steel unlocks Howitzers and the Eiffel Tower. Flight unlocks Biplanes, and Electricity Stock Exchanges. World War: Mass Mobilisation unlocks Infantry, Rocketry Artillery and Armoured Warfare Tanks. Air Power unlocks Fighters and Bombers, and Electronics Research Labs. Modern: Mechanised Warfare unlocks Mechanised Infantry ({RULES.mechanisedInfantryMoves} moves) and Composite Armour Main Battle Tanks. Guided Missiles unlocks Rocket Artillery (range {RULES.rocketArtilleryRange}) and Air Defence. Jet Engines unlocks Jet Fighters and Jet Bombers, and Green Revolution Supermarkets. Future: Autonomous Systems reveals Silicon and unlocks Combat Drones and Autonomous Armour. Robotics unlocks Hunter-Killers. Stealth Technology unlocks Stealth Fighters and Bombers and lets hangars hold 3 aircraft. Fusion Power adds 5 Production in every city and frees Factories and Research Labs from Coal and Oil. Recursive AI reveals the map to your team and adds 20% Production in every city.</dd></div>
      </dl>
      <p>Stored Science carries over when you switch research. Each other empire that knows a technology makes it {RULES.techDiffusionPerEmpire}% cheaper for you, up to {RULES.techDiffusionMax}% in all. This is tech diffusion. Ruins give the first explorer a one-time reward: Gold, Science, population or a free Scout. Every ruin also gives Athens 20 Science.</p>
      <p>After you have researched every technology, choose whether Science yields Gold, Food or Production at 50%. Gold goes to the treasury from the empire’s total Science. Food or Production goes to each city from its own Science. You can change the choice every turn. The research panel forecasts all three, and the yield breakdown names the conversion.</p>
      <h3>Natural wonders</h3>
      <p>Natural wonders are rare landmarks, shown on the map with their bonus on the tile. A wonder cannot hold a city and cannot be improved. Whoever owns its tile controls it: the city whose territory covers the tile gets +{WONDER_PERCENT}% of one of its yields every turn, with no worker needed. The city’s yield breakdown lists it as its own line, and the bonus follows the tile if it changes hands.</p>
      <p>The first empire to see a natural wonder also receives a one-time reward. Natural wonders award no VP. Hover one to see who holds it and what is still on offer. The Settle lens counts an unclaimed wonder near a site.</p>
      <dl className="guide-definitions" aria-label="The eight natural wonders">
        {WONDERS.map((w) => (
          <div key={w}>
            <dt><img src={wonderArt(w, 'b')} width={26} height={26} alt="" /> {WONDER_INFO[w].name}</dt>
            <dd><div>+{WONDER_PERCENT}% {wonderYieldWord(w)}<YieldIcon k={WONDER_INFO[w].yield} size={13} /> to the owning city</div><div>Discovery reward: <Amounts text={wonderRewardText(w)} /></div><div className="muted">Found on {WONDER_INFO[w].terrain[0] === 'Coast' ? 'the coast' : WONDER_INFO[w].terrain[0]}</div></dd>
          </div>
        ))}
      </dl>
    </>;
    case 'combat': return <>
      <p className="guide-lede">Read the forecast. Leave room for the unexpected.</p>
      <h3>Fight on your terms</h3>
      <p>Order a military unit into an enemy unit or city to attack in melee. Both sides can take damage, and wounds normally reduce a unit’s strength. Spartan infantry ignore that penalty. Forests and hills help defenders, but not Mongol military units. Fortification helps every faction. Armies that meet while moving get no terrain or fortification bonus.</p>
      <p>Archers and every other ranged unit fire from up to two tiles away with no retaliation. Choose Ranged attack (<kbd>R</kbd>), then click the target. They cannot shoot and move in the same turn. A ranged unit in one of your cities can turn on Auto-fire from its unit card. It stays there and shoots the best visible enemy in range each turn, or holds when no shot is legal. It never declares War or spends Gold. Moving it or turning Auto-fire off returns it to manual control. A manual shot chooses its target for that turn. While auto-firing, it does not appear in the Return queue.</p>
      <p>One unit does both jobs: the Mongol Keshig, a Cataphract with a bow. It replaces the Cataphract from Iron Working (in the Ancient era the Mongols ride ordinary Horsemen). Each turn it either charges or shoots, never both. To charge, right-click an enemy: it rides onto it, and a charge can take a city. To shoot, press <kbd>R</kbd> and click a target {RULES.keshig.range === 1 ? 'next to it' : `within ${RULES.keshig.range} tiles`}: {unitStatsFor('Mongols', KESHIG_KIND).ranged} ranged from where it stands, with no return fire. A shot never moves it or takes a city. When the forecast offers both, it shows them side by side. A shot fights as a ranged unit and a charge as a mounted one, so neither the melee line nor a mounted target gets a bonus against its arrows. Its next upgrade is a {UNIT_NAME[UNIT_STATS.Cataphract.upgradesTo!]}, which loses the bow.</p>
      <h3>Special units</h3>
      <p>Every empire fields one special unit that replaces a plain unit for its people only. Each is a plain unit with one edge, and every number shows in the unit’s strength breakdown.</p>
      <ul data-testid="guide-special-units">
        {FACTIONS.map((f) => <li key={f}><b>{specialUnitName(f)}</b> ({FACTION_INFO[f].name}) replaces the {UNIT_NAME[SPECIAL_UNIT[f]]}: {specialUnitEdge(f)}.</li>)}
      </ul>
      <h3>Three classes, one triangle</h3>
      <p>Every military unit on land belongs to one of three classes. The <b>melee line</b> (Spearman, Phalangite, Pikeman, Musketman, Rifleman, Trench Infantry, Infantry, Hunter-Killer) counters <b>mounted</b> units. <b>Mounted</b> units (Horseman, Cataphract, Knight, Cuirassier, Cavalry, Early Tank, Tank, Autonomous Armour: {MOUNTED_MOVES} moves, the Early Tank {LANDSHIP_MOVES}, the Tank {TANK_MOVES}, the Autonomous Armour {AUTONOMOUS_ARMOUR_MOVES}) counter <b>ranged</b> units. <b>Ranged</b> units (Archer, Composite Archer, Crossbowman, Arquebusier, Field Cannon, Howitzer, Artillery, Combat Drone) strike the melee line from where it cannot answer. Each class has one unit per era, oldest first as listed. The strength step between eras grows: {RULES.eraCurve.stepPercent.map((p: number) => `${p}%`).join(', ')}. Cities and Walls grow with their owner's era. Siege, a Gold upgrade, lets a unit ignore Walls, and aircraft strike from the air.</p>
      <p>The matchup is a number, never hidden. While both units are from before the {RULES.eraNames[RULES.triangleEndsAtEraTier]} era, the melee line gets +{CLASS_BONUS_PERCENT}% of its strength before bonuses against mounted. Mounted gets the same bonus charging ranged units, but none when they shoot at it. The forecast lists it as its own line. The growing era steps can outweigh a counter's bonus; a counter one era behind is reliable only in the early eras. Ranged has no class bonus: its range is its edge. A horse (Horseman to Cavalry) is stronger than its era's melee line, and it costs more. Charging a city costs a horse {MOUNTED_CITY_PENALTY_PERCENT}% of its strength before bonuses, as its own forecast line; armour, from the Early Tank on, pays nothing. Units upgrade along their line as research opens each era.</p>
      <p><b>Outrider:</b> a horse can ride away from a melee attacker that didn't start the turn beside it; armour, from the Early Tank on, cannot. A horse that stays is attacked; one that moves escapes. A melee unit that started beside it still strikes if it leaves. Ranged fire, city strikes and mounted attacks work as before.</p>
      <p>Every military miniature wears its era on its base as a Roman numeral tab (I for Ancient up to VIII for Future). Each era’s unit has its own figure, so a newer unit of the same class is easy to tell apart at a glance.</p>
      <p>Select one of your military units, and every enemy it could attack this turn shows a chip. A red rising triangle with a number means the enemy is that much stronger in that fight. A green falling triangle means it is weaker. The chip counts the class bonus but not terrain or fortification. Zoomed out, you see only the triangle. The attack forecast gives the full numbers and warns you first when a newer unit outclasses yours.</p>
      <p>No army wins by one class alone. Spearmen hold off horse but die to arrows, archers behind a spear screen are hard to reach on foot, and horse catch archers that stand alone. Watch what your rivals field and change your mix to answer it.</p>
      <p>In your own territory, any unit can upgrade along its line for Gold, plus 1 of the new era’s resource where the new unit needs it. The unit panel shows the price and how it adds up.</p>
      <h3>Aircraft (Machine Age on)</h3>
      <p>Flight unlocks the Biplane. Air Power, in the World War era, unlocks the Fighter and the Bomber. Jet Engines, in the Modern era, unlocks the Jet Fighter and the Jet Bomber. Each uses 1 Oil supply while it exists, including when waiting in a city's hangar. You need spare Oil to start building one; without enough Oil, its strikes and interceptions are {UNSUPPLIED_STRENGTH_PERCENT}% weaker until supply returns. You build aircraft like units, but they live in a city's hangar ({RULES.airBaseCap} per city). Select one from the city's Hangar line or the unit rotation to see its side card and its art on the city. They are never a garrison, cannot be attacked on a tile, never capture and cost no Gold upkeep. They are lost with their city. The map rings what they cover while the aircraft or city is selected. When one is built, a card says what it does.</p>
      <p><b>Biplane.</b> Your team sees every tile within {RULES.aircraftSight} tiles of its city, terrain or not, so your Howitzers can fire at what it spots. Each turn you may order it to strike a visible enemy unit or city within {RULES.biplaneStrikeRange} tiles of its city, with no retaliation. Against a city's HP it does {RULES.biplaneCityDamagePercent}% of the damage. Otherwise it stays on guard and intercepts enemy air strikes within {RULES.biplaneGuardRange} tiles of its city, like a Fighter. Once you know Air Power, choose for each Biplane: upgrade it to a Fighter or to a Bomber.</p>
      <p><b>Bomber.</b> Each turn you may order it to strike a visible enemy unit or city within {RULES.bomberRange} tiles of its city. It takes no retaliation and gets +{siegeBonusOf('Bomber')} against city HP, and the forecast shows the numbers. An idle Bomber is in your Return queue like any unit. Pick the target on the map or in the Air wing, or wait for a target, rebase it or hold it this turn. Terrain never blocks it: it needs only a target in range that you can see. You must be at War, or declare War the same turn. The strike then resolves after the declaration, as a ground attack does.</p>
      <p><b>Fighter.</b> On guard it {interceptRule()}. A Stealth Fighter also stops Stealth Bombers. Stay on guard to keep it that way. Wait stops it asking each turn. Each Fighter intercepts one strike a turn, and a Fighter's own strike can be intercepted too. You can instead order it to strike a visible enemy unit or city within {RULES.fighterStrikeRange} tiles, with its own strength and no city bonus. A Fighter that strikes does not intercept that turn. A Fighter with a target in range asks whether to strike or stay on guard, and This Turn lists the ones on guard.</p>
      <p><b>Jet Fighter and Jet Bomber.</b> Jet Engines upgrades Fighters to Jet Fighters. A Jet Fighter strikes up to {RULES.jetFighterStrikeRange} tiles away and guards {RULES.fighterRange} tiles around its city. Bombers upgrade to Jet Bombers, which strike up to {RULES.jetBomberRange} tiles away, with +{siegeBonusOf('JetBomber')} against city HP.</p>
      <p><b>Air Defence.</b> Guided Missiles unlocks this city building. It meets one air strike a turn on its own city. The strike fails and the aircraft trades damage with a Jet Fighter. The Air Defence takes none and uses no hangar slot. A Stealth Bomber passes it, as it passes every Fighter but a Stealth Fighter. The strike forecast says when a city has one.</p>
      <p>Once you know Stealth Technology, Jet Fighters upgrade to Stealth Fighters and Jet Bombers to Stealth Bombers. A Stealth Fighter strikes up to 7 tiles away and guards 5 tiles around its city. A Stealth Bomber strikes up to 10 tiles away, with +{siegeBonusOf('StealthBomber')} against city HP. Both use Silicon instead of Oil. Only a Stealth Fighter can intercept a Stealth Bomber, and your hangars hold 3 aircraft. An aircraft can move to any other of your cities that has room, at any distance. It cannot strike that turn. The turn report says when a Fighter met a strike.</p>
      <p><b>Sight and Recon.</b> Every aircraft lets your team see every tile within {RULES.aircraftSight} tiles of its city, terrain or not, so a strike at that range needs no scout on the ground. To strike farther out, order a Recon first. Pick any tile within the aircraft's range, and you see the {RULES.reconRadius} tiles around it next turn only. Then order the strike. A Recon uses the aircraft's order, so it cannot strike that turn, and a Fighter that scouts still guards. Press A with an aircraft selected, click a lit tile, and Esc cancels.</p>
      <h3>Sight and terrain</h3>
      <p>Units see two tiles, cities three, and any aircraft {RULES.aircraftSight} around its city. Standing on Hills adds one. Forest and Hills hide the tiles beyond them from low ground, but a hilltop sees over both. Mountains block sight for everyone. The blocking tile and all tiles next to it stay visible. Archers and Crossbowmen need a clear line to shoot two tiles, though adjacent shots always work. Field Cannons need a clear line like other ranged units. {ARTILLERY_RULE} Aircraft shoot over terrain, and so does a walled city: its City fire and the ranged units inside it. Their team must still see the target. A ranged unit in an unwalled city needs a clear line. When you pick a ranged target, red marks available targets and grey marks blocked ones. Inspect a grey target to see what blocks it, then move to a hill or a closer tile, or build Walls in your city.</p>
      <h3>Roads</h3>
      <p>Entering a road tile costs 1 move, whatever the terrain. A unit that starts its turn on a road has +1 move that turn, or +{RULES.railwayMoves} with Railways. Roadworks link cities within 8 tiles, or 12 once their owner knows Railways. Everyone may use every road, rivals and enemies too. A road never opens a border, though. Peace still keeps foreign armies out, except inside the land of whoever holds a Yam Relay Station.</p>
      <p>Roads come two ways, and neither is ever removed. The Mongol Yam Relay Station lays roads once, when it is finished. They link every city on the map to the station’s city, enemy land included. While a station stands, a city founded later is linked the next turn. Any empire can also build Roadworks ({BUILDING_STATS.Roadworks.cost} Production, or buy it with Gold, after Engineering). Roadworks is a one-time build that links its city to every city within 8 tiles, whoever owns it, and to any city founded there later. It also gives +1 Gold. Roads help both sides, so expect your rivals to use them.</p>
      <h3>The Celts</h3>
      <p><b>Barbarians don't attack the Celts.</b> No barbarian camp, scout or raider attacks, shoots or captures a Celtic unit, city or Settler, and a barbarian scout never sends a raid at a Celtic city. This covers every camp, including those the Celts raise. It protects only the Celts, not their teammates or allies. Barbarians never wake a Fortified or Waiting Celtic unit, and never set off an alarm for the Celts. In return, Celtic walled cities and Auto-fire never shoot barbarians. The Celts can still attack barbarians and clear camps by giving the order, and a camp's tile still yields nothing to whoever works it.</p>
      <p>Celts can't keep cities they capture: they sack and burn them. A city you founded comes home intact when you retake it. Each sack carries off {RULES.celtsSackGoldPerPopulation} Gold per population of the city. Sacking a rival’s original capital also scores 1 VP that the Celts keep for the rest of the game: the city is gone, so nobody can take it back.</p>
      <p>A sack also raises a Celtic warband camp, with its guard and scout, on a free tile within 3 tiles of the ruins, in unowned land or Celtic territory. A tile in the territory of a Celtic city that has no camp yet comes first, so a sack can finish <b>Raise the Warbands</b> for that city. The camp counts toward the goal only if it stands in a Celtic city’s territory. If no tile qualifies, there is no camp.</p>
      <p>The battle forecast shows your chance of destroying the defender and of losing the attacker, plus the expected damage to each. It describes the visible matchup, so enemy orders and other attacks can change the result. The kill chance assumes a fortified defender stays fortified, and the card says so. A ranged unit that fires loses its fortification. A melee winner moves onto the defender’s tile. So an attack that can win also lists what waits there next turn: walled cities and visible enemy units that can reach the tile. Each comes with its expected damage and a risk word (Safe, Exposed, Likely lost). Units you cannot see are not counted. When you plot a move, the route avoids steps that known enemies can strike, if a route of the same length exists. It warns you when none does.</p>
      <h3>Veterans</h3>
      <p>Military units that survive a fight earn experience, as in Civ 6. They earn more for melee than for ranged fire, more for attacking, and more against stronger enemies. A kill earns extra experience. Fighting barbarians earns experience only until the first promotion, at {PROMOTION_XP[0]} XP. A unit is promoted automatically at {PROMOTION_XP.join(', ')} XP, up to level {RULES.promotion.maxLevel}. Each level adds {RULES.promotion.strengthPercent}% of its starting strength to its melee and ranged strength. Golden enlisted insignia show the level: one, two, then three chevrons at levels 1–3; levels 4 and 5 add one and two rockers below them. Spartan military units start at level 1, earn XP {RULES.promotion.spartaXpPercent - 100}% faster, and are the only ones to reach level {RULES.promotion.spartaMaxLevel}, Spartan Veteran, with three rockers and a gilt Λ. Upgrades keep promotions. Forecasts list every promotion on both sides.</p>
      <p>Spartans train for war under the agoge. Destroying an enemy military unit, Scouts and barbarians included, restores up to 100 HP. The surviving Spartan attackers who damaged that unit this turn share it.</p>
      <p>Capturing a city fully heals Spartan military units within two tiles. Every Settler and every non-military building costs 50% more Production, except Walls, Castle, Star Fort and Agoge. Military units trained at the Agoge start one level higher. A Hoplite gains +{HOPLITE_PHALANX_STRENGTH} strength next to another Hoplite (the phalanx); it is lost on upgrade.</p>
      <h3>Take cities with the melee line</h3>
      <p>Walled cities fire back, as in Civ 6. Before movement each turn, every city with Walls shoots once. A higher tier such as the Castle or Star Fort counts too, and so does Switzerland’s Alpine Redoubt. The city shoots at the visible enemy military unit with the lowest HP within two tiles, even over Forest, Hills or Mountains, using the city’s strength against the unit’s defence. The city takes no damage, and neither side earns experience. A city knocked to 0 HP stops firing.</p>
      <p>Walls also slow every attack on the city. Attacks on a walled city’s HP do {RULES.walls.damagePercent === 50 ? 'half damage' : `${RULES.walls.damagePercent}% damage`}, from melee and ranged units alike. Hits on a unit, or on a garrison after the city reaches 0 HP, still deal full damage. So a small army cannot simply storm a walled city, and a big one pays for it in time and lives. Air strikes ignore this.</p>
      <p>The answer is Siege, an upgrade you buy for a land military unit once you know Mathematics. It costs {siegeGold('Soldier')} Gold for an Ancient unit and more for later eras, and is bought in your own territory.{SIEGE_USES_IRON ? ' It also uses 1 Iron supply for as long as the unit lives, as the Pikeman does: short of supply, the newest units go idle and fight 25% weaker.' : ''} {SIEGE_RULE}</p>
      <p>A unit with Siege deals full damage to a walled city, and the Walls add nothing to the city’s strength. New technology raises its reach without buying anything again. If the city has a Castle or Star Fort that your technology does not reach yet, the unit deals {RULES.walls.siegePartialPercent}% damage. The unit rests the turn it is bought. The city still fires at Siege units.</p>
      <p>From the Industrial era, guns break walls: a Rifleman, Cavalry, Field Cannon and every later land unit has Siege built in. It ignores Walls, Castles and Star Forts without buying anything, and uses no Iron for it. A Siege unit that upgrades into one keeps the effect and frees its Iron.</p>
      <p>A unit with Siege shows its siege gear beside it on the map: an engine for archers, ladders or a tower for the melee line. Industrial and later units wear none. Rivals see it too. Buy it before the army leaves your land: the army marches as one, so the units you want covered need it first.</p>
      <p>A city without Walls cannot fire at all. Only its city HP and its garrison defend it, which is why an early rush works. Walls are the counter. Walls are drawn as a ring around the city on the map, and the city panel says whether it can fire. When your unit starts within range of a walled city, the forecast for attacking that city shows the expected shot.</p>
      <p>Before the Medieval era, Mongols cannot build Walls, Castles or Star Forts or buy Siege. Walls they capture still protect the captured city. From the Medieval era they build both. Until then Mongols must attack before rivals build Walls, and defend their own open cities with garrisons, fast reinforcements and purchased units.</p>
      <p>A defender fights back once per turn. When several of your units attack the same unit or city in melee in the same movement round, they share its counterattack equally, and the strongest attacker takes any remainder. Units that attack it later that turn take no counterattack. Every attacker still deals its full damage, so ganging up is cheap. Ranged fire never draws a counterattack. A city’s shot and two units meeting head-on work as before.</p>
      <p>The city absorbs damage first. Hits land one at a time. The hit that empties the city’s HP carries on to the garrison with the part of its damage the city did not absorb. Later hits strike the garrison in full. If that kills the garrison and a melee unit attacked the city that round, the strongest such unit captures it at once. Ranged overflow can kill a garrison but never captures. A garrison that steps out of its city that round is not reached.</p>
      <p>Once a city starts a round at 0 HP, attacks hit its garrison directly. A melee unit can march into a fallen city that has no garrison. A ranged unit or two in a threatened city put up a real fight even without Walls, because the city soaks up attacks while they shoot every turn. Cities have 200 HP and regain 20 HP at the end of each turn. They do not regain it if they took damage that turn or an enemy military unit is next to them. Healing from empty to full takes 10 turns.</p>
      <p>A captured city loses half its population, but never drops below 1. A city that returns to its founder keeps its people. It then spends {CAPTURE_RESISTANCE_TURNS} turns in resistance and produces nothing. An empire with no cities and no Settlers is eliminated.</p>
      <p data-testid="guide-occupation-lock"><b>Occupation lock.</b> A conquered city will not accept your rule while its old empire still fights. The unit that captures it stays as the garrison holding it down: it cannot move or disband, and it fortifies by itself (a ranged unit fires at enemies in range). Another unit that steps into the city later is held too. The city itself is frozen: it builds nothing and buys nothing, though its Food, Gold and Science carry on. Both end as soon as you make Peace with the empire you took the city from, or that empire is eliminated. The tile card and the attack forecast warn you before a unit enters or captures such a city.</p>
      <h3>Rest and make space</h3>
      <p>Units that neither move nor fight heal 10 HP a turn, or 20 HP in their own territory. Destroying enemy military units restores up to 100 HP, and taking cities restores more. Stationary military units build +3 fortification each turn, up to +6. Moving or attacking clears it. This resting defence does not take units out of the order cycle.</p>
      <p>Skip (Space) lasts one turn: the unit does nothing and asks for orders again next turn. Fortify (F) is for military units; Wait (F) is for civilians. Heal (H) is for a damaged unit. It rests and heals at the usual rate; the Heal button shows the rate and the turns to full. The turn the unit is at full health the order ends, a notice says so and the unit asks for orders. It wakes early for a new enemy like Fortify and Wait. It heals nothing in closed foreign land, where the button is off. An enemy military unit wakes either order once, with a notice, when it comes into sight within the unit’s full movement range. It counts whether the enemy arrives or walks closer. Sight shared by your team counts, but explored fog does not. Enemies already that close when you choose the order do not wake it again unless they leave that range and return. A different enemy arriving also wakes it. A waiting ranged unit does not fire, and any new order replaces Fortify, Wait or Heal. Units left without orders stay put and return next turn.</p>
      <p>One military unit and one civilian unit fit on a tile. If your unit and a teammate's unit of the same class try to enter the same tile, both stop, so coordinate routes with teammates. An enemy that attacks a departing unit hits it once as it leaves, without its fortification. The unit still completes its move if it survives. Each attack order is one attack. Afterwards the attacker stays where it fought and needs new orders.</p>
      <p>If units of empires that are not at War try to enter the same tile, nobody fights. The side with more total strength moves in and the other stays where it was. Your units and your teammate’s add up, a damaged unit counts for less, and a civilian counts for nothing. Equal strength is decided at random. A unit already on a tile is never pushed off.</p>
    </>;
    case 'victory': return <>
      <p className="guide-lede">Build permanent points. Contest the lead.</p>
      <div className="guide-targets"><div><b>10</b><span>VP · one-empire team</span></div><div><b>20</b><span>VP · two-empire team</span></div><div><b>+10</b><span>target per extra teammate</span></div></div>
      <p>Scores are checked after every turn. Teammates combine their points. Open the score ledger from the top bar’s VP chip or the victory race’s “Score ledger” link. Its columns show teams and empires in rank order, with your column in gilt and the team’s VP over its first member. Every way to score has a row; open a row for its rule and progress. The ledger shows the actual target and standings for your game.</p>
      <h3>Winning · hold the target</h3>
      <p>Reaching the target is not enough: a team wins by VP only after it <b>holds</b> its target at the end of {HOLD_TURNS} turns in a row. The turn the target is reached counts as the first.</p>
      <p>The moment any team reaches its target, every player gets an alarm and a countdown starts, shown in the top bar and the victory track. If that team ends a turn below its target, its count goes back to zero and the turn report says so. The game also ends when only one team survives, or, with a turn limit, when the limit is reached.</p>
      <h3>Winning · hold the last capital</h3>
      <p>Each empire’s first capital is its original capital. A team <b>holds its own</b> while one of its members’ original capitals stands in the hands of that team. Capturing it or razing it (a Celtic sack included) makes it fall; retaking it restores it. A team wins at the end of the turn in which it is the only team still holding an original capital of its own. A team whose capital has fallen can still win by VP, but not this way. If no team holds its own, the game goes on. The Victory race shows each empire’s capital as standing or fallen.</p>
      {decadence.decadenceSlope > 0 && <p><b>Decadence.</b> The further ahead of the pack you are, the more complacent your people grow. Your Power is your total yields (Food, Production, Gold and Science), averaged over the last {RULES.decadence.powerWindowTurns} turns, so a conquest raises it gradually. The average empire is the mean of everyone still alive, you included. One rate applies to every city alike, set by how far your Power is above the average. It slows growth (smaller families) and cuts Production (sloth), Gold (luxury) and Science (complacency) by the same percent. The rate is in proportion to your lead, with no maximum: twice as far ahead, twice the rate. It is {cut(30)}% at 30% ahead, {cut(60)}% at 60% ahead, {cut(100)}% at double the average and {cut(200)}% at triple. At or below the average there is no cut. The same rate is taken from income that is not a city yield, such as Switzerland&rsquo;s interest, and its Gold breakdown shows that cut as its own line. {DECADENCE_FOOD_RULE} A city&rsquo;s Production, Gold and Science breakdowns show each cut as its own &ldquo;Decadence&rdquo; line. Its growth bar&rsquo;s breakdown shows the Food part, and the Victory race shows every empire&rsquo;s lead and rate. Decadence never makes units desert by itself. But if the Gold it leaves you cannot pay your units&rsquo; upkeep, a unit deserts each turn, and the treasury forecast warns you before it happens.</p>}
      <h3>World Ages · <Amount n={1} unit="VP" /> per Age, kept for good</h3>
      <p>The first empire to enter an era begins that era’s Age. If several enter it on the same turn, a random draw picks the first. From that turn, every empire sees the Age’s one card, drawn at random, and it never expires. You can score it once per Age, including an earlier Age you left unscored. Every empire can score the same card. At most one Age scores per turn, the oldest first.</p>
      <p>Each Age draws its card from a mix of peaceful and war cards. The peaceful cards are Patrons (add the Age’s building to more cities), Prosperity (grow your population) and Frontier (gain tiles of territory). Patrons asks for a Laboratory, College, Clearinghouse or Inference Core, by Age. The war cards are Veterans (earn 4 promotions in battle), Humble the mighty (take a city from an empire ahead on VP) and Breach (take a walled city). From the Renaissance, Gain 3 cities can also come up. Peaceful targets grow with the number of empires in the game.</p>
      <p>Every card counts only what you do after its Age begins. Scoring an Age restarts your progress on every other Age you have not scored. Cities, buildings, population, territory and promotions you already had do not count. Humble the mighty and Breach never count a capital or wonder city. The Victory race’s “How you win” block shows each open Age’s card with your progress, and the research screen repeats it. The score ledger shows every Age and who has scored it.</p>
      <h3>Original capitals · <Amount sign="+" n={1} unit="VP" /> each while you hold it</h3>
      <p>The first city an empire founds is its original capital. Hold a rival’s first capital: 1 VP while you hold it. The point moves with the city, like a world wonder’s. If anyone takes the city from you, or it is razed, you lose the point that turn, and a victory hold it was part of can break. Take it again and the point comes back. The one exception is a Celtic sack: the Celts burn the capital and keep its point for good. The founder and its teammates never score their own capital. A star marks every original capital on the map for the whole game, in the colour of the empire that founded it, even after it changes hands. A hollow star means you hold it now. A city that became a capital only after the original was lost has no star and scores nothing. Hover a starred city to read the rule.</p>
      <h3>World wonders</h3>
      <GuideArtRow label="The seven world wonders" pieces={GREAT_WORK_PIECES} />
      <p>Seven of the nine eras unlock a world wonder. Masonry unlocks the Pyramids, Philosophy the Great Library, and Machinery Hagia Sophia. Banking unlocks the Grand Bazaar, Ballistics the Royal Arsenal, Steel the Eiffel Tower, and Fusion Power ITER Fusion Reactor. Each can be completed only once in the world. Each empire may complete at most one. The Pyramids add 1 Production, Hagia Sophia 2 Science, Eiffel Tower 3 Gold and ITER 4 Science in their city; the three existing wonders keep their other rules. All give their tile’s holder 2 VP. Choose an owned land tile within three tiles of the city when you build it. The tile gives up its yield and improvement, stays with the city even when population falls, and changes hands with the city on capture. World wonders must be built with Production.</p>
      <p>Every met rival building a wonder appears on its card. If two cities finish the same wonder on the same turn, the one with more Production left over gets it; an exact tie is a random draw. When another empire finishes first, your city stops building it and asks what to build next. Half its banked Production comes back as Gold, and the turn report names the winner and the refund. A met rival's card line shows its pace, so you can see a race you are losing. Capturing a completed wonder transfers its VP without using your own one; a Celtic sack or a Raze destroys it. Completion permanently uses the builder’s one, even after capture or destruction. Switching builds banks Production until the race ends.</p>
      <h3>Faction goals</h3>
      <p>Every faction except Egypt and Rome has a goal worth {factionGoalVp('Switzerland')} VP. Egypt and Rome have no faction goal yet. Sparta’s, Athens’ and the Aztecs’ goals are earned once and kept for good. India’s, Byzantium’s and the Mongols’ goals go to whoever holds a particular prize, even a rival. Other goals score only while their condition holds. Switzerland’s Reserve, for example, scores only while its treasury holds the target amount.</p>
      <p><b>Rome:</b> A full-health melee veteran (level 1 or higher) can found a city; the unit is consumed. Rome cannot train or buy Settlers. Captured Settlers still work. A Legionary replaces the Phalangite and starts its new city at population 2. A Castrum replaces Walls; upgrading a melee unit in its city restores 50 HP, up to full health, once per order. Founding follows combat, so a wounded founder stays a unit. Rome has no faction goal yet.</p>
      <p>Action goals have a visible button in the Victory race, even while blocked; the disabled button says what is needed. Press G to open an available goal action. Athens can Share the Learning, the Celts can raise warbands, and the Aztecs can kindle the New Fire. In legacy Sakoku games, the country can be closed for the vow. Sparta can retire a veteran from the Victory race or its unit card. When an action first becomes available, This Turn offers it once; Not now keeps its button in the Victory race. The Celts’ Raise the Warbands is offered only when its {factionGoalVp('Celts')} VP would bring you within 1 VP of victory; before that, use its Victory race button. Athens’ Share the Learning is offered only when its {factionGoalVp('Athens')} VP would win you the game; before that, use its Victory race button. Orders are confirmed first and resolve when the turn ends. Share the Learning gives every rival outside Athens’ team {RULES.signalFreeTechs} free technologies, chosen by the rival. A rival that captures an Athenian city also gains one free technology, once per city for each empire. Picks left after an era is finished carry into the next era. A free technology choice you receive stays on your list until you choose.</p>
      <p><b>The Imperial Diwan (India):</b> Indian cities may be founded three tiles apart and get +1 Food; each nearby Indian city adds 7% Food and Production. Non-capital cities send no Gold to the treasury until they build a Revenue Office, which replaces the Market and keeps +3 Gold. Afterwards they send half the Gold they make. Corruption cuts all yields by 10% per tile beyond radius four from the capital, capped at 100%, with a minimum of 3 Production.</p>
      <p>Build a Revenue Office in every city you own to unlock the Imperial Diwan. Whoever holds the city with the Diwan scores {factionGoalVp('India')} VP; capturing it transfers the points.</p>
      <p><b>The New Fire (Aztecs):</b> offer {RULES.swarmPopulation} population in one rite for {factionGoalVp('Aztecs')} VP, kept for good. The biggest cities give population first, every city keeps at least 1, and borders shrink with population. Torches represent the offering; review each city’s population and territory loss before you order it.</p>
      <p><b>Honour the Veterans (Sparta):</b> kept for good. Promote veterans to level {RULES.spartaRetireLevel} or higher, build an Agoge, and retire {RULES.factionGoals.Sparta.target} of them there. A veteran standing in a city with an Agoge is offered "Retire this veteran", and the map marks the cities where he can. Each retired veteran leaves your army for good, and your progress is kept. The last one scores {factionGoalVp('Sparta')} VP. Rivals see only that the goal is done, and a retired army is a thinner one.</p>
      <p><b>Raise the Warbands (Celts):</b> you lose the VP whenever a city has no camp. Once a turn the Celts can raise a warband camp in each Celtic city’s territory that has none, on the farthest free tile. A warband camp is an ordinary barbarian camp with a guard and a scout: it raids your rivals and never the Celts. Borders never disperse it, and its tile yields nothing. The Celts score {factionGoalVp('Celts')} VP while every city they own has a warband camp in its territory. They lose the VP the turn a camp is cleared, and a city founded afterwards has none until the Celts raise one. A rival that clears a camp takes the usual Gold reward; the Celts get none for clearing their own.</p>
      <p><b>Five Ruhr Foundries (Germany):</b> Germany scores {factionGoalVp('Germany')} VP while it owns five cities with a Ruhr Foundry. The Ruhr Foundry replaces the Forge at Iron Working and gives +6 Production when supplied with Iron. Germany loses the VP when its Foundry count drops below five and regains it when the count returns to five. Cities without a Foundry do not affect the goal.</p>
      <p><b>The Heir to the Throne (Byzantium):</b> goes to whoever holds him. Byzantium can train one Heir at a time. He is an expensive civilian and cannot be bought. Every empire is told where he is born, and his position stays public: the map and the minimap mark him every turn, even in fog. Whoever holds him scores {factionGoalVp('Byzantium')} VP, even if he is not their own. To capture him, be at War with his holder and move a military unit onto his tile. Retaking him returns them. Barbarians holding him score nothing, and whoever clears their camp takes him. His holder may disband him, which forfeits the points, and Byzantium can then train another.</p>
      <p><b>The Yam Network (Mongols):</b> follows the Yam Relay Station’s tile. Choose an owned land tile within three tiles of its city when queuing it; the station replaces that tile’s yield and improvement. It costs {BUILDING_STATS.CourierHall.cost} Production, or Gold. Each Mongol empire gets one and can rebuild it if destroyed. Finishing it lays roads between every city on the map and the station’s city, including enemy cities (see Roads). Whoever holds its tile scores {factionGoalVp('Mongols')} VP and opens their land at Peace to all empires’ units. Capturing the city takes the tile, points and open road; a Celtic sack destroys the station. When the holder changes, units standing on land that has just closed must move out.</p>
      <div className="guide-note">Your team score is the sum of its members’ faction goals, scored Age cards, sacked capitals (Celts only), held rival original capitals, and held world wonders. You lose points when you lose a held goal, capital or wonder.</div>
      <h3>When the race ends</h3>
      <p>If several teams finish holding their target on the same turn, the higher VP wins, then the higher population. An exact tie is a draw. With a turn limit, a team still counting down when the limit arrives does not win early. The team with the most VP at that turn wins instead, and tied leaders draw. The last surviving team also wins.</p>
    </>;
    case 'factions': return <>
      <p className="guide-lede">Peoples with different ways to shape history.</p>
      <p>Every faction is playable, with a rule it bends and a weakness that pays for it. Egypt and Rome have no faction goal yet; the other faction goals each score 2 VP.</p>
      <p>Production and Gold figures below are the listed prices.</p>
      <div className="guide-heirs">
        {FACTIONS.map((faction) => {
          const info = FACTION_INFO[faction];
          return <section key={faction} className="guide-heir">
            <div className="guide-heir-head"><FactionSeal faction={faction} size={44} /><h3>{info.name}</h3></div>
            <blockquote>“{info.motto}”</blockquote>
            <p>{FACTION_SHEETS[faction].lore}</p>
            {FACTION_SHEETS[faction].pairs.map((pair, i) => <p key={i}>{pair.strength && <><b>Strength:</b> <Amounts text={pair.strength} /></>}{pair.price && <> <b>Price:</b> <Amounts text={pair.price} /></>}</p>)}
            {/* A sheet whose pair lines already carry the piece's numbers and its comparison (Germany's Foundry) says them once. */}
            {info.unique && <p><Amounts text={FACTION_SHEETS[faction].piecePairs ? uniquePieceBare(faction) : info.unique} /></p>}
            {!FACTION_SHEETS[faction].piecePairs && comparedItems(faction).map((item) => {
              const c = pieceComparison(faction, item);
              return c && <p key={itemKey(item)} className="guide-piece-vs"><Amounts text={comparisonSentence(c)} /></p>;
            })}
            <p className="guide-goal">Goal: <Amounts text={info.goal} /></p>
          </section>;
        })}
      </div>
    </>;
    case 'controls': return <>
      <p className="guide-lede">Keep your attention on the map.</p>
      <dl className="guide-definitions guide-controls">
        <div className="touch-only"><dt>Tap, then tap again</dt><dd>Select a unit, tap a destination for the path and forecast, then tap it again or Confirm to order.</dd></div>
        <div className="touch-only"><dt>Drag / pinch / double-tap</dt><dd>Pan with one finger. Pinch to zoom around both fingers. Double-tap a selected unit or an inspection tile to zoom in; a second destination tap confirms its order.</dd></div>
        <div className="touch-only"><dt>Hold a tile</dt><dd>Open its context actions. Use Select here to change selection.</dd></div>
        <div className="touch-only"><dt>Tap a number / ⓘ</dt><dd>Read a breakdown without issuing an action. Close or tap outside to dismiss.</dd></div>
        <div><dt>Click</dt><dd>Select a unit or city.</dd></div>
        <div><dt>Right-click / drag from unit</dt><dd>Give the selected unit a destination or melee target.</dd></div>
        <div><dt>Drag map / WASD / arrows</dt><dd>Pan the map. Scroll to zoom.</dd></div>
        <div><dt>Space</dt><dd>Skip the selected unit or aircraft for this turn. Aircraft return to the order cycle next turn; a Fighter still intercepts while on guard.</dd></div>
        <div><dt>Tab / Shift+Tab</dt><dd>Move between controls. Use “Cities seen” in This Turn to select any known city, including foreign ones.</dd></div>
        <div className="mouse-only"><dt>Research: click / Shift+click</dt><dd>Click a current-era technology to research it now, moving it to the front while keeping the rest of the queue in order. Shift+click adds a technology to the end of the queue. The card’s Research now and + Queue buttons do the same.</dd></div>
        <div><dt>E</dt><dd>Toggle Auto-explore for a Scout or any military unit. The A badge marks an exploring unit; manual orders take control.</dd></div>
        <div><dt>I</dt><dd>I turns automatic building on or off for the selected city, with the focus you chose last. Shift+I steps through Balanced, Military, Science and Gold. Science and Gold never train military units, even if the city is empty or threatened. Your queue always goes first, and the city never spends Gold. Select several cities in Cities to automate them together.</dd></div>
        <div><dt>H</dt><dd>Heal the selected damaged unit: it rests until its HP is full, then comes back to your orders.</dd></div>
        <div><dt>B / F / R / U</dt><dd>For units: Found city / Fortify or Wait / Ranged attack / Upgrade. F keeps the unit in place until another order or until an enemy military unit comes within its movement range. With an aircraft selected, S opens Strike, A opens Recon, R opens Rebase, and F keeps a Fighter on guard or a Bomber waiting until a target appears. Space skips this turn.</dd></div>
        <div><dt>T</dt><dd>Open Technologies.</dd></div>
        <div><dt>Y / O / N</dt><dd>Turn the map overlays on or off: Yields, Resources and Borders. They stay on over any lens and are remembered on this computer.</dd></div>
        <div><dt>C</dt><dd>Open the Cities overview: every city of yours with its population, Food, Production, Gold, Science, defence and what it is building. Click a heading to sort, click a city to go to it. World wonders and costly buildings say which city builds them fastest, wherever you choose them.</dd></div>
        <div><dt>L</dt><dd>Open or close the Turn report (also Turn report in This Turn). While it is open, <kbd>[</kbd> and <kbd>]</kbd> (or its ◀ ▶) step through the last 20 turns. Lines are marked ▲ good or ▼ bad for you. Click a combat line to centre the map on it, with an arrow from the attacker when you saw where it came from.</dd></div>
        <div><dt>Return</dt><dd>First closes whatever covers the map (the turn report, Diplomacy, research, this guide). Then cycles pending decisions: units, then idle cities, then research. When none remain, end the turn or Ready. Choosing Build advances to the next decision, with mouse, touch or keyboard. To reopen the city, use the Cities overview (<kbd>C</kbd>). + Queue and Shift-click keep the panel open. Escape from a focused control returns to the map.</dd></div>
        <div><dt>Shift+Return</dt><dd>End turn or Ready. If decisions remain, review the list and confirm once or go to the first decision. The End Turn button and Ready anyway use the same review.</dd></div>
        <div><dt>1–8</dt><dd>Switch between local human seats.</dd></div>
        <div><dt>Backspace / Delete</dt><dd>Cancel the selected unit’s pending order.</dd></div>
        <div><dt>Shift + X</dt><dd>Disband the selected unit.</dd></div>
        <div><dt>Escape</dt><dd>Close a panel, cancel targeting, or deselect. On a coach question, Escape only hides the card. The Coach question button, or the Turn report (<kbd>L</kbd>), brings it back.</dd></div>
        <div><dt>A / D</dt><dd>With Diplomacy open: accept or decline the offer awaiting your reply. Diplomacy then moves to the next offer, or closes.</dd></div>
        <div><dt>Z</dt><dd>Undo the answer you just gave, while its notice shows (Ctrl+Z or ⌘Z too). Afterwards, undo it from the offer card or the This Turn pending orders until you end the turn.</dd></div>
        <div><dt>D (Declare War?)</dt><dd>Cancel the declaration, like Escape. Declaring has no key: press its button.</dd></div>
        <div><dt>?</dt><dd>Open this guide. Escape or ? returns to play.</dd></div>
      </dl>
      <p>Gameplay shortcuts work from the map or page background. Enter and Space activate the control that has keyboard focus, and Escape returns focus to the map. Panning also works from plain buttons. Dialogs and menus pause gameplay shortcuts. The turn report does not, though the first Return or Escape closes it. Numbered roundels identify players 1–8 on units and cities. The separate city square or diamond shows population. Territory borders also use distinct line patterns.</p>
      <h3>Save and resume</h3>
      <p>Local games autosave after every turn, and your browser keeps the last 5 turns. Continue on the main menu loads the newest one. If it will not open, Continue offers the turn before it. Orders you have entered this turn are kept too, and come back when you Continue. Resume returns to a game still open. Starting a new game, or opening a file with Load Game, asks first, and replaces the saved game. If the game keeps crashing on the same turn, the crash screen offers Reload on the previous turn, so Continue opens the turn before. If this browser cannot keep your saves, the game says so once. Use Menu → Save to file for a copy that lives on your computer, and Load Game to open one.</p>
      <p>In an online game, the host’s tab keeps the game: a reload carries on, and closing the tab ends it unless the host saved it. To carry on later, the host chooses Save to file in the menu, then Host from a save on the Multiplayer screen. Players rejoin from the game list and take their old seats. The Guide keeps your screen and pending plans in place, but other players can still finish the turn while you read.</p>
      <h3>Help when you need it</h3>
      <p>Open How to Play from the main menu, Menu in a game, or <kbd>?</kbd>. Small first-game tips appear once in this browser. In Settings, switch First-game hints off or choose Reset hints to see them again.</p>
    </>;
    case 'credits': return <Credits />;
  }
}

/** Art licence and the music and CC0 sound credits (app/public/audio/manifest.json). */
function Credits() {
  const music = SOUND_MANIFEST.filter((e) => e.file.startsWith('music/'));
  const sharedMusic = music.length === 2 && music[0].source === music[1].source;
  const packs = [...new Set(SOUND_MANIFEST.filter((e) => e.author === 'Kenney').map((e) => e.title.split(':')[0]))];
  // One line per credited sound: two stings cut from the same recording share one attribution.
  const others = SOUND_MANIFEST.filter((e) => !e.file.startsWith('music/') && e.license === 'CC0-1.0' && e.author !== 'Kenney')
    .filter((e, i, all) => all.findIndex((o) => o.attribution === e.attribution) === i);
  return <>
    <p className="guide-lede">Art and sound.</p>
    <h3>Artwork</h3>
    <p>Legatum’s original artwork is offered under CC BY 4.0 to the extent rights exist. The Niter, Oil and Silicon resource medallions were generated with an OpenAI image model, selected and resized for the game. Their prompts and provenance are in the resource art README.</p>
    <h3>Music</h3>
    {sharedMusic
      ? <p>{music[0].attribution}. The full piece plays on the title screen and during peaceful play; an intense excerpt plays during an empire war. <a href={music[0].source} target="_blank" rel="noreferrer">Source</a></p>
      : <ul>{music.map((e) => <li key={e.file}>{e.attribution} <a href={e.source} target="_blank" rel="noreferrer">Source</a></li>)}</ul>}
    <h3>Sound effects</h3>
    <ul>
      <li>Kenney (kenney.nl), CC0: {packs.join(', ')}.</li>
      {others.map((e) => <li key={e.file}>{e.attribution}.</li>)}
    </ul>
    <p>Sounds were trimmed, loudness-matched and re-encoded; the music loops were crossfaded.</p>
    <details><summary>Full sound credits</summary><ul>{SOUND_MANIFEST.map((e) => <li key={e.file}>
      {e.title} — {e.attribution} ({e.license}). <a href={e.source} target="_blank" rel="noreferrer">Source</a>
    </li>)}</ul></details>
    <h3>Open-source software</h3>
    <p>Legatum’s code is MIT licensed. The game is built on open-source software and bundles the Cormorant and Libre Franklin typefaces under the SIL Open Font License.</p>
    <OpenSourceLicences />
    <p>Legatum is not affiliated with or endorsed by Take-Two Interactive or Firaxis Games. Civilization is a trademark of its owners and is mentioned only to describe the style of game.</p>
  </>;
}

/** Where a distributed build carries its licence notices (tools/release/third-party-licenses.mjs). */
export const LICENCES_URL = `${import.meta.env.BASE_URL ?? './'}THIRD_PARTY_LICENSES.txt`;

/** The third-party licence notices, read when first opened: they are long, and only release builds carry them. */
function OpenSourceLicences() {
  const [text, setText] = useState<string | null>(null);
  const load = async () => {
    if (text !== null) return;
    try {
      const response = await fetch(LICENCES_URL);
      // A development server answers a missing file with the app's own page.
      const found = response.ok && (response.headers.get('content-type') ?? '').startsWith('text/plain');
      setText(found ? await response.text() : '');
    } catch {
      setText('');
    }
  };
  return <details className="guide-licences" onToggle={(e) => { if (e.currentTarget.open) void load(); }}>
    <summary>Open-source licences</summary>
    {text === null ? <p>Loading…</p>
      : text ? <pre tabIndex={0}>{text}</pre>
      : <p>This build does not carry the licence notices. They ship with the release builds and are listed in THIRD_PARTY_NOTICES.md in the source code.</p>}
  </details>;
}
